create table "ITEAM"."ETUDIANT" (
   "NOM"    varchar2(50 byte),
   "PRENOM" varchar2(50 byte),
   "ID"     number generated by default as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 start with
   1 cache 20 noorder nocycle nokeep noscale not null enable
)
segment creation immediate
pctfree 10
pctused 40
initrans 1
maxtrans 255 nocompress
logging
   storage ( initial 65536 next 1048576 minextents 1 maxextents 2147483645 pctincrease 0 freelists 1 freelist groups 1 buffer_pool
   default flash_cache default cell_flash_cache default )
tablespace "USERS";

insert into etudiant (
   "ID",
   "NOM",
   "PRENOM"
) values
   ( 1,
     'Dupont',
     'Jean' );

declare
   v_nom    "ITEAM".etudiant.nom%type;
   v_prenom "ITEAM".etudiant.prenom%type;
begin
   select nom,prenom into
      v_nom,
      v_prenom
     from "ITEAM".etudiant
    where "ITEAM".etudiant.id = 1;
   dbms_output.put_line('Étudiant : '
                        || v_prenom
                        || ' ' || v_nom);
exception
   when no_data_found then
      dbms_output.put_line('Aucun étudiant trouvé');
end;
/

/*
Il existe plusieurs types de blocs : anonymes (comme ci-dessus, non stockés), procédures, fonctions, 
packages et triggers (stockés dans la base). Les blocs peuvent être imbriqués ; une variable déclarée dans 
un bloc interne masque celle du bloc externe :  
*/

declare
   v_x number := 1;
begin
   declare
      v_x number := 2;
   begin
      dbms_output.put_line('Interne : ' || v_x);
   end;
   dbms_output.put_line('Externe : ' || v_x);
end;
/ 

/*Variables, constantes et types*/

insert into etudiant (
   "ID",
   "NOM",
   "PRENOM"
) values
   ( 2,
   'Durand',
   'Marie' );

declare
   c_seuil    constant number(
      4,
      2
   ) := 10;
   v_compteur pls_integer := 0;
   v_message  varchar2(100) default 'Bonjour';
   v_actif    boolean := true;
   v_etu      etudiant%rowtype;
   v_nom      etudiant.nom%type;
begin
   select *
   into v_etu
   from etudiant
   where id = 2;
   dbms_output.put_line(v_etu.id
                        || ' '
                        || v_etu.prenom
                        || ' ' || v_etu.nom);
end;
/

/*SQL dans PL/SQL*/

CREATE TABLE "ITEAM"."NOTE" 
   (	"ID" NUMBER, 
	"NOTE" FLOAT(126), 
	"ID_ELEVE" NUMBER DEFAULT '0', 
	"CODE_MODULE" VARCHAR2(21 BYTE)
   ) SEGMENT CREATION IMMEDIATE 
PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
NOCOMPRESS LOGGING
STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
TABLESPACE "USERS" ;
ALTER TABLE "ITEAM"."NOTE" ADD CONSTRAINT "NOTE_PK" PRIMARY KEY ("ID")
USING INDEX PCTFREE 10 INITRANS 2 MAXTRANS 255 COMPUTE STATISTICS 
STORAGE(INITIAL 65536 NEXT 1048576 MINEXTENTS 1 MAXEXTENTS 2147483645
PCTINCREASE 0 FREELISTS 1 FREELIST GROUPS 1
BUFFER_POOL DEFAULT FLASH_CACHE DEFAULT CELL_FLASH_CACHE DEFAULT)
TABLESPACE "USERS"  ENABLE;



INSERT INTO "ITEAM"."NOTE" ("ID", "NOTE", "ID_ELEVE", "CODE_MODULE") VALUES (1, 10, 1, 'BD');
INSERT INTO "ITEAM"."NOTE" ("ID", "NOTE", "ID_ELEVE", "CODE_MODULE") VALUES (2, 15, 2, 'BD');



DECLARE   
v_nb PLS_INTEGER; 
BEGIN   
   UPDATE "ITEAM"."NOTE" SET "NOTE" = "NOTE" + 1    
   WHERE "CODE_MODULE" = 'BD' AND "NOTE" < 20;
   v_nb := SQL%ROWCOUNT;     
   DBMS_OUTPUT.PUT_LINE(v_nb || ' note(s) modifiée(s)');   ROLLBACK;                 
END; 
/ 

DECLARE 
   v_note NUMBER := 13.5;
   v_res  VARCHAR2(20);
   v_res0  VARCHAR2(20);
BEGIN
   IF v_note >= 16 THEN
      v_res := 'Très bien';            
   ELSIF v_note >= 12 THEN 
      v_res := 'Bien';
   ELSIF v_note >= 10 THEN
      v_res := 'Passable';
   ELSE 
      v_res := 'Ajourné';
   END IF;
-- CASE de recherche (searched CASE)
   v_res0 := CASE              
            WHEN v_note >= 10 THEN 'Admis' 
            ELSE 'Rattrapage'
      END;
   DBMS_OUTPUT.PUT_LINE(v_res0 || ' - ' || v_res);
END;
/ 
--- LOOP, WHILE, FOR 
DECLARE
   i PLS_INTEGER := 1;
BEGIN
   LOOP EXIT WHEN i > 3;
      DBMS_OUTPUT.PUT_LINE('LOOP  : ' || i);    
      i := i + 1;   
   END LOOP; 
   i := 1;
   WHILE i <= 3 LOOP
      DBMS_OUTPUT.PUT_LINE('WHILE : ' || i);     
      i := i + 1;
   END LOOP; 
   -- FOR (le compteur est déclaré implicitement)
   FOR k IN 1..3 LOOP
      DBMS_OUTPUT.PUT_LINE('FOR   : ' || k);
   END LOOP;
   FOR k IN REVERSE 1..3 LOOP 
      DBMS_OUTPUT.PUT_LINE('REVERSE : ' || k);  
   END LOOP;
END;
/ 